insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('RO', 'default', 'Planul de conturi general (clasele 1-7)', '{}'::jsonb, true, 'companies', array['RO-OMFP-BS', 'RO-OMFP-IS']::text[], null, 'Ordinul ministrului finanțelor publice nr. 1.802/2014, pct. 14 și anexă — Planul de conturi general, cu nouă clase (1-9). Acest pachet transcrie un subset funcțional al claselor 1-7 (capitaluri, imobilizări, stocuri, terți, trezorerie, cheltuieli, venituri), folosind exact codurile oficiale ale conturilor sintetice de gradul I și II; clasele 8 (conturi speciale, în afara bilanțului) și 9 (conturi de gestiune, contabilitate de gestiune internă) nu sunt reluate, fiind opționale și fără corespondent direct în formularul de TVA sau în situațiile financiare prescurtate. Câteva conturi analitice de gradul II fără o subdiviziune oficială fixă (de exemplu 6588) sunt o convenție a acestui pachet, semnalată în README', 'omfp-1802-2014')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

