insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('RO', 'RO-P-11', 'Achiziții — cota redusă 11%', '{}'::jsonb, null, 'percent', 11, 'purchase', 'domestic', date '2025-08-01', null, 'Codul fiscal, art. 291 alin. (2), astfel cum a fost modificat de art. II pct. 42 din Legea nr. 141/2025 — cota redusă de 11%; art. 297 și art. 298 — dreptul de deducere.', null, null, 90, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'legea-141-2025', null, null, null, null),
  ('RO', 'RO-P-21', 'Achiziții — cota standard 21%', '{}'::jsonb, null, 'percent', 21, 'purchase', 'domestic', date '2025-08-01', null, 'Codul fiscal, art. 291 alin. (1), astfel cum a fost modificat de art. II pct. 42 din Legea nr. 141/2025 — cota standard de 21%; art. 297 și art. 298 — dreptul de deducere a taxei aferente achizițiilor destinate operațiunilor taxabile.', null, null, 80, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'legea-141-2025', null, null, null, null),
  ('RO', 'RO-P-EXT-21', 'Achiziție de servicii de la un prestator din afara Uniunii — taxare inversă 21%', '{}'::jsonb, null, 'percent', 21, 'purchase', 'foreign_services_received', date '2025-08-01', null, 'Codul fiscal, art. 278 alin. (2) și art. 307 alin. (2) — regula generală B2B plasează prestarea la sediul beneficiarului stabilit în România, indiferent dacă prestatorul este stabilit în Uniune sau în afara ei; beneficiarul este obligat la plata taxei prin taxare inversă. Formularul 300 nu separă cele două cazuri: rd. 7/22 le cuprinde pe amândouă, ca și rândul VJ3 al modelului italian descris în docs/packs.md.', null, null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'codul-fiscal', null, null, null, null),
  ('RO', 'RO-P-ICG-21', 'Achiziție intracomunitară de bunuri — taxare inversă 21%', '{}'::jsonb, null, 'percent', 21, 'purchase', 'intracom_acquisition_goods', date '2025-08-01', null, 'Codul fiscal, art. 273 — achiziția intracomunitară de bunuri este operațiune impozabilă; art. 308 — cumpărătorul înregistrat în scopuri de TVA colectează taxa prin taxare inversă, o înscrie atât ca taxă colectată (rd. 5 din formularul 300), cât și, în măsura dreptului de deducere, ca taxă deductibilă (rd. 20) — o singură bază, reluată în cele două rânduri, exact ca la achiziția intracomunitară estoniană din docs/packs.md.', 'K', 'VATEX-EU-IC', 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'codul-fiscal', null, null, null, null),
  ('RO', 'RO-P-ICS-21', 'Achiziție de servicii intracomunitare — taxare inversă 21%', '{}'::jsonb, null, 'percent', 21, 'purchase', 'intracom_acquisition_services', date '2025-08-01', null, 'Codul fiscal, art. 278 alin. (2) și art. 307 alin. (2) — beneficiarul stabilit în România al unui serviciu generic prestat de o persoană impozabilă stabilită în alt stat membru este obligat la plata taxei prin taxare inversă. Formularul 300 nu rezervă rd. 7/22 exclusiv serviciilor intracomunitare: același rând cuprinde și achizițiile de bunuri și servicii de la persoane neînregistrate în România, altele decât cele de la rd. 5/20 — a se vedea RO-P-EXT-21.', 'K', 'VATEX-EU-IC', 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'codul-fiscal', null, null, null, null),
  ('RO', 'RO-P-IMPORT-21', 'Import de bunuri — cota standard 21%', '{}'::jsonb, null, 'percent', 21, 'purchase', 'import', date '2025-08-01', null, 'Codul fiscal, art. 291 alin. (1); art. 326 — taxa datorată pentru importul de bunuri se stabilește prin declarația vamală. Instrucțiunile formularului 300 nu rezervă un rând distinct importurilor: rd. 24 cuprinde « baza de impozitare și taxa aferentă importurilor care nu se încadrează în prevederile art. 326 alin. (4) și (5) », alături de achizițiile interne cu cota de 21%. Regimul de amânare a plății TVA la import (art. 326 alin. (4)-(5), «taxare prin decontul de taxă», des utilizat de importatorii înregistrați) rămâne nemodelat: formularul însuși îl exclude din rd. 24/25 fără să-i rezerve un alt rând — a se vedea secțiunea «From Romania» din docs/international.md.', null, null, 100, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'd300-formular', null, null, null, null),
  ('RO', 'RO-S-11', 'Vânzări — cota redusă 11%', '{}'::jsonb, null, 'percent', 11, 'sale', 'domestic', date '2025-08-01', null, 'Codul fiscal, art. 291 alin. (2), astfel cum a fost modificat de art. II pct. 42 din Legea nr. 141/2025 — cota redusă unică de 11%, care înlocuiește de la 1 august 2025 cele două cote reduse anterioare de 9% și 5%, pentru: medicamente de uz uman; alimente și băuturi destinate consumului uman și animal (cu excepția băuturilor alcoolice, a celor de la codul NC 2202 și a produselor cu peste 10 g zahăr/100 g, altele decât laptele praf pentru nou-născuți); apă și canalizare; îngrășăminte și pesticide de uz agricol; manuale școlare, cărți, ziare și reviste; acces la castele, muzee, monumente, grădini zoologice și botanice; lemn de foc și peleți; energie termică furnizată populației și anumitor instituții în sezonul rece (1 noiembrie — 31 martie); locuințe ca parte a politicii sociale; cazare hotelieră; servicii de restaurant și catering (cu aceleași excepții privind băuturile).', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'legea-141-2025', null, null, null, null),
  ('RO', 'RO-S-21', 'Vânzări — cota standard 21%', '{}'::jsonb, null, 'percent', 21, 'sale', 'domestic', date '2025-08-01', null, 'Codul fiscal, art. 291 alin. (1), astfel cum a fost modificat de art. II pct. 42 din Legea nr. 141/2025 — cota standard de 21%, aplicabilă de la 1 august 2025 (anterior 19%, de la 1 ianuarie 2017).', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'legea-141-2025', null, null, null, null),
  ('RO', 'RO-S-EXE', 'Operațiuni financiare scutite — dobânzi pentru credite acordate', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2007-01-01', null, 'Codul fiscal, art. 292 alin. (2) lit. a) pct. 1 — scutirea fără drept de deducere pentru acordarea și negocierea de credite, precum și gestiunea creditelor de către persoana care le acordă, inclusiv dobânzile aferente, transpunând art. 135 alin. (1) lit. b) din Directiva 2006/112/CE. Codul VATEX-EU-135 este un cod generic pentru articolul 135; alegerea sa aici, în locul unui cod mai specific dacă lista VATEX ar publica unul, este de reconfirmat de un contabil.', 'E', 'VATEX-EU-135', 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'codul-fiscal', null, null, null, null),
  ('RO', 'RO-S-EXPORT', 'Export de bunuri — scutit cu drept de deducere', '{}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2016-01-01', null, 'Codul fiscal, art. 294 alin. (1) lit. a) — scutire cu drept de deducere pentru livrarea de bunuri expediate sau transportate în afara Uniunii Europene de către furnizor sau de altă persoană în contul acestuia. Rândul formularului 300 nu numește explicit exportul: acest pachet îl declară la rd. 14 « Livrări de bunuri și prestări de servicii scutite cu drept de deducere, altele decât cele de la rd. 1-3 », singurul rând rămas pentru o scutire cu drept de deducere care nu este nici o livrare intracomunitară (rd. 1), nici o operațiune al cărei loc de livrare este în afara României (rd. 3) — o lectură a formularului și nu o casetă dedicată exportului, de reverificat de un contabil.', 'G', 'VATEX-EU-G', 30, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'd300-formular', null, null, null, null),
  ('RO', 'RO-S-ICG', 'Livrare intracomunitară de bunuri — scutită', '{}'::jsonb, null, 'percent', 0, 'sale', 'intracom_goods', date '2007-01-01', null, 'Codul fiscal, art. 294 alin. (2) lit. a) — scutire cu drept de deducere pentru livrarea intracomunitară de bunuri către o persoană care îi comunică furnizorului un cod valabil de înregistrare în scopuri de TVA dintr-un alt stat membru, transpunând art. 138 din Directiva 2006/112/CE.', 'K', 'VATEX-EU-IC', 40, 'vat', true, array['transport_evidence', 'buyer_status']::tax_condition[], null, false, false, null, 'codul-fiscal', null, null, null, null),
  ('RO', 'RO-S-ICS', 'Prestare de servicii intracomunitară — neimpozabilă în România', '{}'::jsonb, null, 'percent', 0, 'sale', 'intracom_services', date '2010-01-01', null, 'Codul fiscal, art. 278 alin. (2) — locul prestării unui serviciu generic către o persoană impozabilă este locul unde beneficiarul este stabilit; taxa se datorează, prin taxare inversă, de beneficiarul stabilit în alt stat membru (art. 44 și 196 din Directiva 2006/112/CE).', 'K', 'VATEX-EU-IC', 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'codul-fiscal', null, null, null, null),
  ('RO', 'RO-S-RC-331', 'Livrare supusă taxării inverse — măsuri de simplificare', '{}'::jsonb, null, 'percent', 0, 'sale', 'domestic_reverse_charge', date '2016-01-01', null, 'Codul fiscal, art. 331 alin. (2) — printre bunurile și serviciile supuse măsurilor de simplificare (taxare inversă) se numără cerealele și plantele tehnice, potrivit casetei « livrare de cereale și plante tehnice » a formularului 300; taxa este datorată de beneficiar, care o înregistrează în decontul propriu, iar factura se emite fără TVA, cu mențiunea « taxare inversă ».', 'AE', 'VATEX-EU-AE', 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'codul-fiscal', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

