insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('RO', 'RO-D300', 'Decont de taxă pe valoarea adăugată (formularul 300)', array['month', 'quarter']::declaration_period[], 'month'::declaration_period, date '2026-01-01', null, 'Ordinul președintelui ANAF nr. 174/2026, anexele 1-2 — modelul și instrucțiunile de completare ale formularului (300), aplicabile începând cu declararea obligațiilor fiscale aferente primei perioade fiscale a anului 2026. Acest pachet transcrie rândurile pe care taxele sale le declară și cele patru totaluri finale (19, 30, 31, 35, 36, 37, 44, 45); rândurile de regularizări (2, 4, 6, 8, 16, 18, 21, 23, 28, 33, 34), cele exclusiv informative (3.1, 5.1, 7.1, 12.1, 12.2, 20.1, 22.1, 26.1, 26.2, 29.1) și reportul soldurilor între perioade (rd. 38, 39, 41, 42) nu sunt reluate — a se vedea README.md și secțiunea «From Romania» din docs/international.md.', true,'day_of_month_after_period'::filing_deadline_rule, 25, null, 'Codul fiscal, art. 323 alin. (1) — decontul de taxă se depune până la data de 25 inclusiv a lunii următoare celei în care se încheie perioada fiscală.', 'codul-fiscal', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

