values
  ('RO', 'RO-D300', '1', 'base', 'Livrări intracomunitare de bunuri, scutite conform art. 294 alin. (2) lit. a) și d) din Codul fiscal', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formularul 300, rd. 1.', 'd300-formular'),
  ('RO', 'RO-D300', '3', 'base', 'Livrări de bunuri sau prestări de servicii pentru care locul livrării/prestării este în afara României, precum și livrări intracomunitare scutite conform art. 294 alin. (2) lit. b) și c) din Codul fiscal', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formularul 300, rd. 3.', 'd300-formular'),
  ('RO', 'RO-D300', '5', 'base', 'Achiziții intracomunitare de bunuri pentru care cumpărătorul este obligat la plata TVA (taxare inversă)', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formularul 300, rd. 5.', 'd300-formular'),
