  ('RO', 'RO-D300', '7', 'base', 'Achiziții de bunuri, altele decât cele de la rd. 5, și achiziții de servicii pentru care beneficiarul din România este obligat la plata TVA (taxare inversă)', '{}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formularul 300, rd. 7.', 'd300-formular'),
