  ('RO', 'RO-D300', '10', 'tax', 'Taxa aferentă livrărilor de la rd. 10', '{}'::jsonb, 100, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formularul 300, rd. 10, coloana taxă.', 'd300-formular'),
  ('RO', 'RO-D300', '13', 'base', 'Livrări de bunuri și prestări de servicii supuse măsurilor de simplificare (taxare inversă)', '{}'::jsonb, 110, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formularul 300, rd. 13 — rând informativ, fără TVA facturată.', 'd300-formular'),
  ('RO', 'RO-D300', '14', 'base', 'Livrări de bunuri și prestări de servicii scutite cu drept de deducere, altele decât cele de la rd. 1-3', '{}'::jsonb, 120, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formularul 300, rd. 14.', 'd300-formular'),
  ('RO', 'RO-D300', '15', 'base', 'Livrări de bunuri și prestări de servicii scutite fără drept de deducere', '{}'::jsonb, 130, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formularul 300, rd. 15.', 'd300-formular'),
  ('RO', 'RO-D300', '19', 'total', 'TOTAL TAXĂ COLECTATĂ', '{}'::jsonb, 140, null, array['5:tax', '7:tax', '9:tax', '10:tax']::text[], '{}'::text[], null, null, false, false, null, 'Formularul 300, rd. 19 — suma taxei de la rd. 1 până la rd. 18; acest pachet nu modelează regularizările (rd. 2, 4, 6, 8, 16, 18), care rămân la zero.', 'd300-formular'),
  ('RO', 'RO-D300', '20', 'base', 'Achiziții intracomunitare de bunuri pentru care cumpărătorul este obligat la plata TVA (taxare inversă) — parte deductibilă', '{}'::jsonb, 150, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formularul 300, rd. 20.', 'd300-formular'),
  ('RO', 'RO-D300', '20', 'tax', 'Taxa dedusă aferentă rd. 20', '{}'::jsonb, 160, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formularul 300, rd. 20, coloana taxă.', 'd300-formular'),
  ('RO', 'RO-D300', '22', 'base', 'Achiziții de bunuri, altele decât cele de la rd. 20, și achiziții de servicii pentru care beneficiarul din România este obligat la plata TVA (taxare inversă) — parte deductibilă', '{}'::jsonb, 170, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formularul 300, rd. 22.', 'd300-formular'),
  ('RO', 'RO-D300', '22', 'tax', 'Taxa dedusă aferentă rd. 22', '{}'::jsonb, 180, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formularul 300, rd. 22, coloana taxă.', 'd300-formular'),
  ('RO', 'RO-D300', '24', 'base', 'Achiziții de bunuri și servicii taxabile cu cota de 21%, altele decât cele de la rd. 27, precum și importuri care nu se încadrează în prevederile art. 326 alin. (4) și (5) din Codul fiscal', '{}'::jsonb, 190, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formularul 300, rd. 24.', 'd300-formular'),
  ('RO', 'RO-D300', '24', 'tax', 'Taxa dedusă aferentă rd. 24', '{}'::jsonb, 200, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formularul 300, rd. 24, coloana taxă.', 'd300-formular'),
  ('RO', 'RO-D300', '25', 'base', 'Achiziții de bunuri și servicii, taxabile cu cota de 11%', '{}'::jsonb, 210, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formularul 300, rd. 25.', 'd300-formular'),
  ('RO', 'RO-D300', '25', 'tax', 'Taxa dedusă aferentă rd. 25', '{}'::jsonb, 220, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formularul 300, rd. 25, coloana taxă.', 'd300-formular'),
  ('RO', 'RO-D300', '30', 'total', 'TOTAL TAXĂ DEDUCTIBILĂ', '{}'::jsonb, 230, null, array['20:tax', '22:tax', '24:tax', '25:tax']::text[], '{}'::text[], null, null, false, false, null, 'Formularul 300, rd. 30 — suma taxei de la rd. 20 până la rd. 28; acest pachet nu modelează compensația în cotă forfetară pentru agricultori (rd. 27, 28) și lasă-le la zero.', 'd300-formular'),
  ('RO', 'RO-D300', '31', 'total', 'Sub-total taxă dedusă conform art. 297 și art. 298 sau art. 300 și art. 298 din Codul fiscal și compensație în cotă forfetară', '{}'::jsonb, 240, null, array['30']::text[], '{}'::text[], null, null, false, false, null, 'Formularul 300, rd. 31 — restrângerea prin pro rata (art. 300) nu este modelată de acest pachet, care reia integral rd. 30; a se vedea secțiunea «From Romania» din docs/international.md.', 'd300-formular'),
  ('RO', 'RO-D300', '35', 'total', 'TOTAL TAXĂ DEDUSĂ', '{}'::jsonb, 250, null, array['31']::text[], '{}'::text[], null, null, false, false, null, 'Formularul 300, rd. 35 — rd. 31 + rd. 32 + rd. 33 + rd. 34; rd. 32 (TVA restituită călătorilor străini), rd. 33 (regularizări) și rd. 34 (ajustări pro rata) nu sunt modelate și rămân la zero.', 'd300-formular'),
