update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = 30,
  late_payment_reference        = 'Legea nr. 72/2013, art. 3 — dobânda legală penalizatoare curge de plin drept de la data scadenței, fără nicio notificare prealabilă; art. 4 — în lipsa unei dobânzi convenite, se aplică dobânda legală penalizatoare stabilită conform art. 3 din Ordonanța Guvernului nr. 13/2011, la nivelul ratei dobânzii de referință a Băncii Naționale a României în vigoare în prima zi calendaristică a semestrului, majorată cu 8 puncte procentuale.',
  numbering_legal_reference     = 'Codul fiscal, art. 319 alin. (20) lit. a) — factura cuprinde în mod obligatoriu «numărul de ordine, în baza uneia sau a mai multor serii, care identifică factura în mod unic». Legea cere doar un număr secvențial și unic, ca și la art. 106e ust. 1 pkt 2 din legea poloneză a TVA — nici continuitate fără goluri, nici o remitere la zero anuală nu sunt impuse de text; seria anuală (an în număr) este o convenție larg răspândită în practică, posibil precizată doar în Normele metodologice de aplicare (Hotărârea Guvernului nr. 1/2016), text pe care cercetarea acestui pachet nu l-a putut verifica separat.',
  numbering_source_key          = 'codul-fiscal',
  payment_terms_legal_reference = 'Legea nr. 72/2013, art. 3 alin. (1) — dobânda curge după 30 de zile calendaristice de la data primirii facturii sau, dacă data primirii facturii este incertă ori anterioară recepției bunurilor/serviciilor, de la data recepției acestora.',
  payment_terms_source_key      = 'legea-72-2013',
  tax_point_rule                = 'invoice_if_issued',
  tax_point_legal_reference     = 'Codul fiscal, art. 281 alin. (1) — faptul generator intervine la data livrării bunurilor sau la data prestării serviciilor, cu regulile speciale ale alin. (7)-(8) pentru livrări/prestări continue sau cu decontări succesive; art. 282 alin. (1) — exigibilitatea taxei intervine, ca regulă, la data faptului generator; art. 282 alin. (2) lit. a) — derogare: dacă factura este emisă înainte de data faptului generator, exigibilitatea intervine la data emiterii facturii. Nemodelat: art. 282 alin. (2) lit. b) — un avans încasat înainte de faptul generator face taxa exigibilă la data încasării, o derogare pe care acest câmp nu poate exprima decât prin cash_basis pe o taxă anume, ca și în Belgia sau Luxemburg.',
  tax_point_source_key          = 'codul-fiscal',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Ordonanța de urgență a Guvernului nr. 120/2021, cu modificările ulterioare — sistemul național RO e-Factura este obligatoriu în relația B2B dintre persoane impozabile stabilite în România începând cu 1 iulie 2024 (perioadă de grație fără sancțiuni până la 31 decembrie 2024; sancțiuni aplicabile de la 1 iulie 2025), cu un termen de transmitere de 5 zile lucrătoare de la data emiterii facturii. Factura electronică este redactată în format UBL 2.1, potrivit specificațiilor tehnice CIUS-RO aprobate prin Ordinul ministrului finanțelor nr. 1.366/2021, modificat prin Ordinul nr. 4.092/2022 — un profil conform modelului semantic EN 16931, spre deosebire de FatturaPA (Italia) sau de schema XML națională FA(3) (Polonia). Dar RO e-Factura n-a rămas pentru asta un schimb descentralizat între parteneri: art. 4 alin. (4)-(6) din OUG 120/2021 dispune că, dacă factura respectă structura impusă, sistemul aplică «sigiliul electronic al Ministerului Finanțelor» și abia atunci o comunică destinatarului, iar «exemplarul original al facturii electronice se consideră fișierul de tip XML însoțit de sigiliul electronic al Ministerului Finanțelor» — nu fișierul emis de vânzător. Cumpărătorul primește deci o copie sigilată de stat, nu factura direct de la vânzător: o clearance de tip CTC, ca și SdI-ul italian sau KSeF-ul polonez, deși construită pe un format nominal EN 16931. Niciun brick din packages/formats/ nu scrie, validează sau transmite azi o factură conformă CIUS-RO (regulile Schematron BR-RO-* nu sunt implementate); profile și mandatory_from rămân deci vide, ca la Italia și Polonia, mai degrabă decât să afirme o interoperabilitate pe care acest depozit n-o oferă încă — a se vedea secțiunea «From Romania» din docs/international.md. vat_scheme și party_scheme rămân de asemenea vide: canalul RO e-Factura identifică părțile prin codul de identificare fiscală (CIF), nu printr-o schemă ISO 6523 verificată oficial; o eventuală schemă Peppol pentru context transfrontalier nu a putut fi confirmată dintr-o sursă oficială românească în cadrul acestei cercetări.',
  einvoice_source_key           = 'oug-120-2021',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = array['camt.053', 'mt940']::text[],
  payment_formats               = array['pain.001']::text[],
  fiscal_year_default           = 'calendar'
 where country = 'RO';

insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('RO', 'reverse_charge', 'reverse_charge', 'Taxare inversă', '{}'::jsonb, 10, date '1970-01-01', null, 'Codul fiscal, art. 319 alin. (20) — mențiunile obligatorii ale facturii, printre care mențiunea corespunzătoare atunci când beneficiarul este persoana obligată la plata taxei.'),
  ('RO', 'intracom_goods', 'intra_eu_goods', 'Scutit de TVA — livrare intracomunitară de bunuri, art. 294 alin. (2) lit. a) din Codul fiscal.', '{}'::jsonb, 20, date '1970-01-01', null, 'Codul fiscal, art. 319 alin. (20) — mențiunea corespunzătoare unei operațiuni scutite, cu trimitere la dispoziția legală aplicabilă; art. 294 alin. (2) lit. a) — livrarea intracomunitară de bunuri scutită, transpunând art. 138 din Directiva 2006/112/CE.'),
  ('RO', 'intracom_services', 'intra_eu_services', 'Taxare inversă — prestare de servicii intracomunitară, art. 278 alin. (2) din Codul fiscal.', '{}'::jsonb, 30, date '1970-01-01', null, 'Codul fiscal, art. 319 alin. (20); art. 278 alin. (2) — regula generală B2B, locul prestării la sediul beneficiarului, care devine persoana obligată la plata taxei (art. 44 și 196 din Directiva 2006/112/CE).'),
  ('RO', 'export', 'export', 'Scutit de TVA — export, art. 294 alin. (1) din Codul fiscal.', '{}'::jsonb, 40, date '1970-01-01', null, 'Codul fiscal, art. 319 alin. (20); art. 294 alin. (1) lit. a) — scutirea cu drept de deducere pentru bunurile expediate sau transportate în afara Uniunii Europene de către furnizor.'),
  ('RO', 'exempt', 'exempt', 'Scutit de TVA, art. 292 din Codul fiscal.', '{}'::jsonb, 50, date '1970-01-01', null, 'Codul fiscal, art. 319 alin. (20); art. 292 — scutirile fără drept de deducere pentru anumite activități de interes general și pentru alte operațiuni.'),
  ('RO', 'late_payment', 'late_payment', 'În caz de întârziere la plată, se datorează de plin drept dobânda legală penalizatoare prevăzută de Legea nr. 72/2013, precum și o indemnizație forfetară de recuperare a creanței.', '{}'::jsonb, 60, date '1970-01-01', null, 'Legea nr. 72/2013, art. 3 și art. 13 — dobânda legală penalizatoare și indemnizația forfetară de recuperare a creanței, datorate fără punere în întârziere.')
